// Minimal reimplementation of moneyed.Money limited to the behaviour the
// original script exercises: construction, `<` comparison and str().

import { getCurrency } from './currencies.mjs';
import {
  numberToDecimalParts,
  roundHalfEven,
  groupThousands,
} from './decimal.mjs';

// Raised for the same condition as Python's decimal.InvalidOperation when a
// NaN amount takes part in a comparison.
export class InvalidOperation extends Error {
  constructor() {
    super("[<class 'decimal.InvalidOperation'>]");
    this.name = 'InvalidOperation';
  }
}

export class Money {
  constructor(amount, currency) {
    // moneyed stores the amount as Decimal(str(amount)); the JS double is
    // the same value, and its decimal digits are recovered at format time.
    this.amount = amount;
    this.currency = getCurrency(currency);
  }

  lt(other) {
    if (Number.isNaN(this.amount) || Number.isNaN(other.amount)) {
      throw new InvalidOperation();
    }
    return this.amount < other.amount;
  }

  toString() {
    const { symbol, digits } = this.currency;
    const amount = this.amount;
    const negative = amount < 0 || Object.is(amount, -0);

    let numberText;
    if (!Number.isFinite(amount)) {
      // Babel formats infinite values as the infinity symbol, no decimals.
      numberText = '∞';
    } else {
      const parts = numberToDecimalParts(amount);
      const rounded = roundHalfEven(parts.intPart, parts.fracPart, digits);
      numberText = groupThousands(rounded.intPart);
      if (digits > 0) {
        numberText += '.' + rounded.fracPart;
      }
    }
    // en_US currency pattern: "¤#,##0.00" with a plain leading minus.
    return (negative ? '-' : '') + symbol + numberText;
  }
}

