// Reimplementation of CPython's float(str) parsing for argparse's
// type=float conversion, including its error message shape.

// Python float() accepts surrounding ASCII whitespace, an optional sign,
// decimal digits with single underscores between digits, an optional
// fraction (including a bare trailing dot), an optional exponent, and the
// case-insensitive words "inf", "infinity" and "nan".
const FLOAT_RE = /^[+-]?(?:(?:\d(?:_\d)*)(?:\.(?:\d(?:_\d)*)?)?|\.\d(?:_\d)*)(?:[eE][+-]?\d(?:_\d)*)?$/;
const SPECIAL_RE = /^[+-]?(?:inf(?:inity)?|nan)$/i;

export class InvalidFloatValue extends Error {
  constructor(raw) {
    super(`invalid float value: ${pythonRepr(raw)}`);
    this.name = 'InvalidFloatValue';
    this.raw = raw;
  }
}

// Python repr() of a (short, ASCII-ish) string: single quotes by default.
function pythonRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else out += ch;
  }
  return out + quote;
}

export function parsePythonFloat(raw) {
  // Python strips leading/trailing whitespace (str.strip() set).
  const s = raw.replace(/^[\t\n\v\f\r ]+|[\t\n\v\f\r ]+$/g, '');
  if (SPECIAL_RE.test(s)) {
    const lower = s.toLowerCase();
    const neg = lower.startsWith('-');
    if (lower.includes('nan')) return NaN;
    return neg ? -Infinity : Infinity;
  }
  if (!FLOAT_RE.test(s)) {
    throw new InvalidFloatValue(raw);
  }
  return Number(s.replace(/_/g, ''));
}

