// Replicates: prefix matching with ambiguity detection, "--opt value" and
// "--opt=value", the negative-number heuristic, "--" handling, -h/--help,
// required-argument and unrecognized-argument errors, exit codes 0/2 and the
// 80-column usage wrapping of argparse's HelpFormatter.

import { writeSync } from 'node:fs';
import { parsePythonFloat } from './pyfloat.mjs';

const PREFIX = 'usage: ';
const TEXT_WIDTH = 78; // argparse: (terminal width 80) - 2, when not a tty

const ACTIONS = [
  { optionStrings: ['-h', '--help'], dest: 'help', takesArg: false, required: false },
  { optionStrings: ['--amount1'], dest: 'amount1', takesArg: true, type: 'float', required: true },
  { optionStrings: ['--amount2'], dest: 'amount2', takesArg: true, type: 'float', required: true },
  { optionStrings: ['--currency'], dest: 'currency', takesArg: true, type: 'str', required: true },
];

const ACTION_USAGES = [
  '[-h]',
  '--amount1 AMOUNT1',
  '--amount2 AMOUNT2',
  '--currency CURRENCY',
];

const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

const ALL_OPTION_STRINGS = ACTIONS.flatMap((a) => a.optionStrings);
const BY_EXACT = new Map();
for (const action of ACTIONS) {
  for (const s of action.optionStrings) {
    BY_EXACT.set(s, action);
  }
}

function actionName(action) {
  return action.optionStrings.join('/');
}

export function formatUsage(prog) {
  const usage = prog + ' ' + ACTION_USAGES.join(' ');
  if (PREFIX.length + usage.length <= TEXT_WIDTH) {
    return PREFIX + usage + '\n';
  }
  // argparse splits the option usages into whitespace-separated tokens
  // (its part_regexp matches \S+ for non-grouped items) and wraps greedily.
  const parts = [prog, ...ACTION_USAGES.flatMap((u) => u.split(' '))];
  const indent = ' '.repeat(PREFIX.length + prog.length + 1);
  const lines = [];
  let line = [];
  let lineLen = PREFIX.length - 1;
  for (const part of parts) {
    if (lineLen + 1 + part.length > TEXT_WIDTH && line.length > 0) {
      lines.push(line);
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  lines.push(line);
  let out = PREFIX + lines[0].join(' ') + '\n';
  for (const rest of lines.slice(1)) {
    out += indent + rest.join(' ') + '\n';
  }
  return out;
}

export function formatHelp(prog) {
  return (
    formatUsage(prog) +
    '\n' +
    'options:\n' +
    '  -h, --help           show this help message and exit\n' +
    '  --amount1 AMOUNT1\n' +
    '  --amount2 AMOUNT2\n' +
    '  --currency CURRENCY\n'
  );
}

class ParserExit extends Error {
  constructor(code) {
    super(`parser exit ${code}`);
    this.code = code;
  }
}

