  if (tok.length === 1) return false; // a bare '-' is a value
  let name = tok;
  const eq = tok.indexOf('=');
  if (eq !== -1) {
    name = tok.slice(0, eq);
    if (BY_EXACT.has(name)) return true;
  }
  const tuples = matchLongPrefix(name);
  if (tuples.length > 1) {
    fail(
      prog,
      `ambiguous option: ${name} could match ${tuples
        .map((t) => t.optionString)
        .join(', ')}`,
    );
  }
