        continue;
      }
      if (tok === '--') {
        // First '--': everything after it is positional; the marker itself
        // shows up among the unrecognized arguments (Python 3.13 argparse).
        positionalOnly = true;
        extras.push('--');
        i += 1;
        continue;
      }
      if (looksLikeOption(prog, tok)) {
        let name = tok;
        let explicit;
        const eq = tok.indexOf('=');
        if (tok.startsWith('--') && eq !== -1) {
          name = tok.slice(0, eq);
          explicit = tok.slice(eq + 1);
        }
        let action;
        if (BY_EXACT.has(name)) {
          action = BY_EXACT.get(name);
        } else {
          const tuples = matchLongPrefix(name);
          if (tuples.length > 1) {
            fail(
              prog,
              `ambiguous option: ${name} could match ${tuples
                .map((t) => t.optionString)
                .join(', ')}`,
            );
          }
