        if (explicit !== undefined) {
          raw = explicit;
        } else {
          const next = argv[i + 1];
          if (next === undefined || next === '--' || looksLikeOption(prog, next)) {
            fail(prog, `argument ${actionName(action)}: expected one argument`);
          }
          raw = next;
          i += 1;
        }
        if (action.type === 'float') {
          try {
            values[action.dest] = parsePythonFloat(raw);
          } catch (e) {
            fail(prog, `argument ${actionName(action)}: ${e.message}`);
          }
        } else {
          values[action.dest] = raw;
        }
        i += 1;
      } else {
        extras.push(tok); // positional, but this parser defines none
        i += 1;
      }
    }

    const missing = ACTIONS.filter((a) => a.required && !(a.dest in values));
    if (missing.length > 0) {
      fail(
        prog,
