          .map(actionName)
          .join(', ')}`,
      );
    }
    if (extras.length > 0) {
      fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
    }
  } catch (e) {
    if (e instanceof ParserExit) {
      process.exitCode = e.code;
      return null;
    }
    throw e;
  }
  return values;
}

