// Entry point — JS port of /workspace/dataset/test19.py
//
//   import argparse
//   from moneyed import Money
//   ...
//   if m1 < m2: smaller = m1
//   else:       smaller = m2
//   print(smaller)

import { basename } from 'node:path';
import { writeSync } from 'node:fs';
import { parseArgs } from './argparse.mjs';
import { Money, InvalidOperation } from './money.mjs';
import { CurrencyDoesNotExist } from './currencies.mjs';

const prog = basename(process.argv[1] || 'test19.mjs');

const args = parseArgs(process.argv.slice(2), prog);
if (args === null) {
  // Help was shown (exit 0) or a parse error was reported (exit 2).
} else {
  let m1;
  let m2;
  try {
    m1 = new Money(args.amount1, args.currency);
    m2 = new Money(args.amount2, args.currency);
  } catch (e) {
    if (e instanceof CurrencyDoesNotExist) {
      // moneyed.classes.CurrencyDoesNotExist -> traceback, exit code 1
      writeSync(2, `moneyed.classes.CurrencyDoesNotExist: ${e.message}\n`);
      process.exitCode = 1;
    } else {
      throw e;
    }
  }

  if (m1 !== undefined) {
    let smaller;
    try {
      smaller = m1.lt(m2) ? m1 : m2;
    } catch (e) {
      if (e instanceof InvalidOperation) {
        // decimal.InvalidOperation on NaN comparison -> traceback, exit 1
        writeSync(2, `decimal.InvalidOperation: ${e.message}\n`);
        process.exitCode = 1;
      } else {
        throw e;
      }
    }
    if (smaller !== undefined) {
      writeSync(1, smaller.toString() + '\n');
    }
  }
}

